import {readFile,writeFile,mkdir,rename,stat} from 'node:fs/promises';
import {spawn,spawnSync} from 'node:child_process';
import {createHash,randomUUID} from 'node:crypto';
import {resolve} from 'node:path';
const root=resolve('.local/step07-review/independent-round13');
const own=JSON.parse(await readFile('.local/postgres/ownership.json','utf8'));
if(resolve(own.root)!==process.cwd()||own.port!==55505||own.database!=='tileset_studio')throw Error('Ownership mismatch');
if((await stat('.env')).mode%512!==384)throw Error('Environment mode mismatch');
process.loadEnvFile('.env');
const u=new URL(process.env.DATABASE_URL);
if(u.port!=='55505'||u.hostname!=='127.0.0.1'||u.pathname!=='/tileset_studio'||u.password!==own.password)throw Error('Database mismatch');
Object.assign(process.env,{PATH:'/Users/dingshinn/.nvm/versions/node/v22.21.1/bin:/opt/homebrew/opt/postgresql@14/bin:'+process.env.PATH,API_PORT:'4405',WEB_PORT:'5305',INTEGRATION_API_PORT:'4405',STEP07_TEST_API_PORT:'4405',TILESET_PG_BIN:'/opt/homebrew/opt/postgresql@14/bin',TILESET_ASSET_ROOT:resolve('.local/step07-review/assets'),PLAYWRIGHT_BROWSERS_PATH:root+'/browser-cache'});
const actions={install:['pnpm',['exec','playwright','install','--with-deps','chromium']],check:['pnpm',['check']],capture:['pnpm',['exec','vitest','run','apps/api/tests/studio/received-resources.test.ts']],migrate:['pnpm',['db:migrate']],api:['pnpm',['test:integration']],privacy:['pnpm',['test:dev-privacy']],http:['pnpm',['test:step07']],production:['pnpm',['test:e2e']],dev:['pnpm',['test:e2e']],probe:['node',[root+'/probe.mjs']],probe2:['node',[root+'/probe2.mjs']],probe3:['node',[root+'/probe3.mjs']],engineering:['node',['scripts/build-engineering.mjs','step07']]};
const name=process.argv[2];if(!actions[name])throw Error('Invalid action');
const noenv=['production','dev'].includes(name);if(name==='dev')process.env.E2E_MODE='dev';else delete process.env.E2E_MODE;
await mkdir(root+'/private',{recursive:true});
const held=root+'/private/env-held';
let fixture;
if(noenv){
 const database='tileset_review13_'+name+'_'+randomUUID().replaceAll('-','');
 const created=spawnSync('/opt/homebrew/opt/postgresql@14/bin/psql',['-h','127.0.0.1','-p','55505','-U','tileset','-d','tileset_studio','-v','ON_ERROR_STOP=1','-c','CREATE DATABASE "'+database+'"'],{env:{...process.env,PGPASSWORD:own.password},encoding:'utf8'});
 if(created.status!==0)throw Error('Fresh owned database creation failed');
 u.pathname='/'+database;process.env.DATABASE_URL=u.href;
 process.env.TILESET_ASSET_ROOT=root+'/assets-'+name;
 const migration=spawnSync('pnpm',['--filter','@tileset/api','exec','prisma','migrate','deploy'],{env:process.env,encoding:'utf8'});
 await writeFile(root+'/private/'+name+'-migration.log',migration.stdout+migration.stderr,{flag:'wx',mode:0o600});
 if(migration.status!==0)throw Error('Fresh owned database migration failed');
 fixture={newDatabase:true,databaseNameSHA256:createHash('sha256').update(database).digest('hex'),migrationExit:0,assetRoot:'assets-'+name};
 await writeFile(root+'/private/'+name+'-fixture.json',JSON.stringify({database,assetRoot:process.env.TILESET_ASSET_ROOT},null,2)+'\n',{flag:'wx',mode:0o600});
 await rename('.env',held);
}
const [cmd,args]=actions[name],start=new Date(),chunks=[];
try{
 const child=spawn(cmd,args,{env:process.env,stdio:['ignore','pipe','pipe']});
 for(const stream of [child.stdout,child.stderr])stream.on('data',b=>chunks.push(Buffer.from(b)));
 const result=await new Promise((res,rej)=>{child.on('error',rej);child.on('close',(exit,signal)=>res({exit,signal}));});
 const raw=Buffer.concat(chunks);await writeFile(root+'/private/'+name+'.log',raw,{flag:'wx',mode:0o600});
 let safe=raw.toString().replaceAll(own.password,'[REDACTED_SECRET]').replaceAll(process.env.DATABASE_URL,'[REDACTED_DATABASE_URL]').replace(/postgres(?:ql)?:\/\/[^\s"']+/g,'[REDACTED_DATABASE_URL]');
 await writeFile(root+'/evidence/'+name+'.log.txt',safe,{flag:'wx'});
 const receipt={name,command:cmd+' '+args.join(' '),started:start.toISOString(),ended:new Date().toISOString(),seconds:(Date.now()-start.getTime())/1000,...result,noEnvFile:noenv,fixture,node:process.version,privateLog:{path:'private/'+name+'.log',bytes:raw.length,sha256:createHash('sha256').update(raw).digest('hex')}};
 await writeFile(root+'/evidence/'+name+'.result.json',JSON.stringify(receipt,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify(receipt));console.log(safe.slice(-1900));process.exitCode=result.exit??1;
}finally{if(noenv)await rename(held,'.env');}
